import java.io.*;
import java.util.*;

public class HeightAllTheSame {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = reader.readLine().split(" ");
        long N = Long.parseLong(parts[0]);
        long M = Long.parseLong(parts[1]);
        long L = Long.parseLong(parts[2]);
        long R = Long.parseLong(parts[3]);

        long totalCount = R - L + 1;
        long evenCount = totalCount / 2 + (totalCount % 2 == 0 && L % 2 == 0 ? 1 : 0);
        long oddCount = totalCount - evenCount;

        long answer;
        if ((N * M) % 2 == 1) {
            answer = fastPower(evenCount + oddCount, N * M);
        } else {
            answer = (fastPower(evenCount + oddCount, N * M) + fastPower(evenCount - oddCount, N * M)) % mod;
            answer = (answer * modInverse(2)) % mod;
        }
        System.out.println(answer);
    }

    static long mod = 998244353;

    static long modInverse(long x) {
        return fastPower(x, mod - 2);
    }

    static long fastPower(long base, long exp) {
        long result = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }
}
